function piRenderAirbnbConnect(job) {
  var box = document.getElementById('pi-airbnb-connect');
  if (!box) return;
  if (!job) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.style.display = 'block';
  var st = String(job.status || '');
  var body = '';
  if (st === 'starting' || st === 'logging_in') {
    body = '<div style="font-weight:600;margin-bottom:6px">Connecting Airbnb…</div>' +
      '<div style="color:var(--tx3);font-size:12.5px">' + (job.hint || 'Please wait') + '</div>' +
      '<div style="margin-top:10px"><button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button></div>';
  } else if (st === 'awaiting_otp') {
    body = '<div style="font-weight:600;margin-bottom:6px">Enter Airbnb verification code</div>' +
      '<div style="color:var(--tx3);font-size:12.5px;margin-bottom:8px">' + (job.hint || 'Check email/SMS for the code Airbnb just sent.') + '</div>' +
      '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">' +
      '<input id="pi-airbnb-otp" type="text" inputmode="numeric" autocomplete="one-time-code" placeholder="6-digit code" ' +
      'style="width:140px;padding:7px 10px;border:1px solid var(--bdr);border-radius:8px;background:var(--bg2);font-size:14px" />' +
      '<button class="btn gold" onclick="piSubmitAirbnbOtp()">Submit code</button>' +
      '<button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button>' +
      '</div>';
  } else if (st === 'connected') {
    body = '<div style="font-weight:600;color:var(--tx-ok,#059669)">✓ Airbnb connected</div>' +
      '<div style="color:var(--tx3);font-size:12.5px;margin-top:4px">' + (job.hint || '') + '</div>';
  } else if (st === 'error') {
    body = '<div style="font-weight:600;color:var(--tx-err,#b91c1c)">Connect failed</div>' +
      '<div style="font-size:12.5px;margin-top:4px">' + (job.error || 'Unknown error') + '</div>' +
      '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">' +
      '<button class="btn sm gold" onclick="piConnectAirbnbInApp()">Try again</button>' +
      '<button class="btn sm" onclick="piConnectSessionPaste(\'airbnb\')">Paste session JSON</button>' +
      '<button class="btn sm" onclick="piCancelAirbnbConnect()">Dismiss</button></div>';
  }
  box.innerHTML = body;
  var inp = document.getElementById('pi-airbnb-otp');
  if (inp) setTimeout(function () { try { inp.focus(); } catch (e) {} }, 50);
}
window.piCancelAirbnbConnect = async function () {
  var id = window._piAirbnbLoginId;
  if (id) {
    try { await fetch('/api/platform-invoices/sessions/airbnb/login/' + encodeURIComponent(id) + '/cancel', { method: 'POST' }); } catch (e) {}
  }
  window._piAirbnbLoginId = null;
  if (window._piAirbnbLoginTimer) { clearInterval(window._piAirbnbLoginTimer); window._piAirbnbLoginTimer = null; }
  piRenderAirbnbConnect(null);
};
window.piPollAirbnbConnect = async function () {
  var id = window._piAirbnbLoginId;
  if (!id) return;
  try {
    var r = await fetch('/api/platform-invoices/sessions/airbnb/login/' + encodeURIComponent(id)).then(function (x) { return x.json(); });
    if (!r.ok || !r.job) throw new Error((r && r.error) || 'poll failed');
    piRenderAirbnbConnect(r.job);
    if (r.job.status === 'connected') {
      if (window._piAirbnbLoginTimer) { clearInterval(window._piAirbnbLoginTimer); window._piAirbnbLoginTimer = null; }
      msg('Airbnb connected in-app', true);
      await piReload();
      setTimeout(function () { piRenderAirbnbConnect(null); }, 2500);
    } else if (r.job.status === 'error') {
      if (window._piAirbnbLoginTimer) { clearInterval(window._piAirbnbLoginTimer); window._piAirbnbLoginTimer = null; }
      msg(r.job.error || 'Connect failed', false);
    }
  } catch (e) {
    msg(e.message || String(e), false);
  }
};
window.piConnectAirbnbInApp = async function () {
  msg('Starting Airbnb connect…', true);
  try {
    var res = await fetch('/api/platform-invoices/sessions/airbnb/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}'
    });
    var j = await res.json();
    if (!res.ok || !j.ok) throw new Error((j && j.error) || (j && j.hint) || 'connect start failed');
    window._piAirbnbLoginId = j.job && j.job.id;
    piRenderAirbnbConnect(j.job);
    if (window._piAirbnbLoginTimer) clearInterval(window._piAirbnbLoginTimer);
    window._piAirbnbLoginTimer = setInterval(function () { piPollAirbnbConnect(); }, 2000);
    await piPollAirbnbConnect();
  } catch (e) {
    msg(e.message || String(e), false);
    piRenderAirbnbConnect({ status: 'error', error: e.message || String(e) });
  }
};
window.piSubmitAirbnbOtp = async function () {
  var id = window._piAirbnbLoginId;
  var inp = document.getElementById('pi-airbnb-otp');
  var otp = inp ? String(inp.value || '').trim() : '';
  if (!id) { msg('No active Airbnb connect — click Connect Airbnb', false); return; }
  if (!/^\d{4,8}$/.test(otp)) { msg('Enter the 4–8 digit code from Airbnb', false); return; }
  msg('Submitting Airbnb code…', true);
  try {
    var res = await fetch('/api/platform-invoices/sessions/airbnb/login/' + encodeURIComponent(id) + '/otp', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ otp: otp })
    });
    var j = await res.json();
    if (!res.ok && !(j && j.job)) throw new Error((j && j.error) || 'OTP failed');
    if (j.job) piRenderAirbnbConnect(j.job);
    if (j.job && j.job.status === 'connected') {
      if (window._piAirbnbLoginTimer) { clearInterval(window._piAirbnbLoginTimer); window._piAirbnbLoginTimer = null; }
      msg('Airbnb connected in-app', true);
      await piReload();
      setTimeout(function () { piRenderAirbnbConnect(null); }, 2500);
    } else if (j.job && j.job.status === 'awaiting_otp') {
      msg(j.job.hint || 'Enter the newest code', false);
    } else if (!res.ok) {
      throw new Error(j.error || 'OTP failed');
    }
  } catch (e) { msg(e.message || String(e), false); }
};
